package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.util.regex.Pattern;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** Reads the body: a split needs the amount it splits off, a number with up to two decimals. */
public class ValidateSplit {
    private static final Pattern AMOUNT = Pattern.compile("\\d{1,15}(\\.\\d{1,2})?");

    public void validate(@RequestBody SplitRequest request, Out<ClaimSplit> split) throws InvalidClaimStatusException {
        String amount = request == null || request.amount() == null ? "" : request.amount().trim();
        if (!AMOUNT.matcher(amount).matches()) {
            throw new InvalidClaimStatusException("A split needs the amount it splits off, with up to two decimals");
        }
        split.set(new ClaimSplit(new BigDecimal(amount).setScale(2), request.by() == null ? "" : request.by().trim()));
    }
}
package net.officefloor.hq.app.claim;

/** The new claim a split made, as stored (the claim it was split from stays the pipeline's Claim). */
public record SplitOff(Claim claim) {
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.role.RoleRepository;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/**
 * Takes the split amount off the claim: it keeps the rest of its amount and loses any figure a statement bound it to.
 * Only an OPEN claim that is not deferred (see ClaimDue#deferred) nor whose due-by falls inside a closed period is split, only by
 * an amount more than 0.00 and less than its amount, and only by a user whose role the sheet lets open a claim (the
 * new claim is theirs to open; see SettingRepository#permits).
 */
public class ApplySplit {
    public void apply(@Val Claim claim, @Val ClaimSplit split, SheetRepository sheets, PeriodRepository periods,
            SettingRepository settings, RoleRepository roles, Out<Claim> changed) throws InvalidClaimStatusException {
        if (claim.status() != ClaimStatus.OPEN) {
            throw new InvalidClaimStatusException("Only an OPEN claim can be split");
        }
        if (ClaimDue.deferred(claim, sheets.today(claim.sheetId()))) {
            throw new InvalidClaimStatusException("A deferred claim cannot be split");
        }
        if (periods.closedOn(claim.sheetId(), claim.dueBy())) {
            throw new InvalidClaimStatusException("The claim's due-by is inside a closed period");
        }
        if (split.amount().signum() <= 0 || split.amount().compareTo(claim.amount()) >= 0) {
            throw new InvalidClaimStatusException("A split takes more than 0.00 and less than the claim's amount");
        }
        String role = roles.roleOf(claim.sheetId(), split.by());
        if (!settings.permits(claim.sheetId(), "open", role)) {
            throw new InvalidClaimStatusException("A " + role + " may not open a claim");
        }
        changed.set(new Claim(claim.id(), claim.sheetId(), claim.personId(), claim.amount().subtract(split.amount()),
                claim.date(), claim.note(), claim.status(), claim.number(), claim.due(), claim.openedBy(), false, null,
                claim.corrects(), claim.dueBy(), claim.deferredUntil(), claim.proofs(), claim.splitFrom(), claim.ref(), claim.tags(), claim.held()));
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.holiday.HolidayRepository;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/**
 * Stores the claim's remaining amount, but only while it is still OPEN with the amount the split started from (a
 * change another user made first is refused), then adds the new claim: the split-off amount, the same person, date
 * and note, its due-by fixed now as the terms-th business day after its date (the terms in force on the day it is split, see ClaimRules#terms), OPEN with the sheet's next
 * number (see ClaimNumbering), opened by the user who split, the original's number as split-from and its tags; a late entry when its
 * due-by falls inside a soft-closed period. The new claim's
 * status log starts with its OPEN line (see ClaimLog).
 */
public class SaveSplit {
    public void save(@Val Claim claim, @Val ClaimSplit split, ClaimRepository claims, PersonRepository people,
            PeriodRepository periods, SettingRepository settings, HolidayRepository holidays, SheetRepository sheets, ClaimLog log,
            Out<SplitOff> made) throws InvalidClaimStatusException {
        if (!claims.split(claim, claim.amount().add(split.amount()))) {
            throw new InvalidClaimStatusException("The claim was changed by someone else");
        }
        Person person = people.find(claim.sheetId(), claim.personId());
        int terms = person == null ? settings.terms(claim.sheetId(), settings.today(claim.sheetId())) : ClaimRules.terms(person, settings);
        Claim added = claims.add(claim.sheetId(), claim.personId(), split.amount(), claim.date(), claim.note(), null, null, claim.tags(),
                holidays.businessDaysAfter(claim.sheetId(), claim.date(), terms), terms);
        if (periods.softClosedOn(added.sheetId(), added.dueBy())) {
            claims.markLateEntry(added);
        }
        String number = ClaimNumbering.next(added, claims, periods, settings, sheets);
        Claim opened = new Claim(added.id(), added.sheetId(), added.personId(), added.amount(), added.date(),
                added.note(), ClaimStatus.OPEN, number, null, split.by(), false, null, null, added.dueBy(), null, 0,
                claim.number(), null, added.tags(), false);
        claims.updateStatus(opened, ClaimStatus.DRAFT);
        claims.splitFrom(opened);
        log.write(opened, split.by());
        made.set(new SplitOff(opened));
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.rollup.RollupBefore;
import net.officefloor.plugin.variable.Val;

/** Writes CLAIM_SPLIT to the audit file once the split is stored, naming the original claim with its remaining amount
 *  and ending into=<new number>, then CLAIM_OPENED for the new claim, then the figures the change moved (see Rollup). */
public class RecordClaimSplit {
    public void record(@Val Claim claim, @Val SplitOff made, @Val ClaimSplit split, PersonRepository people,
            @Val RollupBefore before, Rollup rollup, Audit audit) {
        Person person = people.find(claim.sheetId(), claim.personId());
